function migDiff(oldT,newT){var stmts=[];var oldCols={},newCols={};
oldT.columns.forEach(function(c){oldCols[c.name]=c;});newT.columns.forEach(function(c){newCols[c.name]=c;});
Object.keys(newCols).forEach(function(n){if(!oldCols[n])stmts.push('ALTER TABLE '+newT.name+' ADD COLUMN '+n+' '+newCols[n].type+';');});
Object.keys(oldCols).forEach(function(n){if(!newCols[n])stmts.push('ALTER TABLE '+newT.name+' DROP COLUMN '+n+';');});
Object.keys(newCols).forEach(function(n){if(oldCols[n]&&oldCols[n].type!==newCols[n].type)stmts.push('ALTER TABLE '+newT.name+' ALTER COLUMN '+n+' TYPE '+newCols[n].type+';');});
return stmts;}
function migScript(name,stmts){return '-- migration: '+name+'\nBEGIN;\n'+stmts.join('\n')+'\nCOMMIT;';}

